import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"可证明安全与归约","description":"","frontmatter":{"title":"可证明安全与归约","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/provable-security-reduction.md","filePath":"cs/provable-security-reduction.md","lastUpdated":1789023840000}'),h={name:"cs/provable-security-reduction.md"};function E(u,a,A,_,m,b){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="可证明安全与归约" tabindex="-1">可证明安全与归约 <a class="header-anchor" href="#可证明安全与归约" aria-label="Permalink to &quot;可证明安全与归约&quot;">​</a></h1><div class="epigraph"><p>证明不是「没人破过」，而是：若敌手能赢这个游戏，就能构造算法赢那个被认为难的问题。归约把产品安全感绑到假设上；假设外的误用，证明沉默。</p><footer>—— Goldwasser and Micali, Probabilistic Encryption, 1984；Bellare and Rogaway 的游戏化方法；Katz and Lindell</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/homomorphic-intuition">同态</a>把电路评在密文上。本单元从一次一密走到外包计算，缺口是把<strong>游戏与归约</strong>收成方法论：IND-CPA/CCA、EUF-CMA、ROM。不把证明助手课的 Coq 再讲一遍；那是形式核，这里是密码学归约。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shannon 完善保密不需计算假设。其余原语都有假设：PRP、RSA、LWE。可证明安全：写清敌手能力与获胜条件，给归约。随机预言机模型把哈希当理想黑盒，现实哈希只是近似。缺口是读证明时要问「假设是什么、游戏禁了什么」。</p><h3 id="证明不管实现" tabindex="-1">证明不管实现 <a class="header-anchor" href="#证明不管实现" aria-label="Permalink to &quot;证明不管实现&quot;">​</a></h3><p>归约不管计时、nonce 复用、填充预言。那些在游戏外，误用课收。</p><p><span class="marginnote">GM 1984 语义安全。Bellare–Rogaway 把实践协议游戏化。本课不伪造论文。seL4 更后是系统形式化，对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 IND-CPA 游戏回顾对称。指出一次一密是信息论，AES-GCM 是计算+nonce 合同。签名用 EUF-CMA。强调具体安全（优势、时间）比渐近一句话有用。</p>',12)),(e(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%8D%8F%E8%AE%AE%E6%95%8C%E6%89%8B%22%5D%20--%3E%20RED%5B%22%E5%BD%92%E7%BA%A6%22%5D%0A%20%20RED%20--%3E%20HARD%5B%22%E6%89%93%E7%A0%B4%E5%81%87%E8%AE%BE%E9%97%AE%E9%A2%98%22%5D%0A%20%20GAME%5B%22%E6%B8%B8%E6%88%8F%E5%89%8D%E6%8F%90%22%5D%20--%3E%20ADV%0A%20%20MIS%5B%22%E5%89%8D%E6%8F%90%E5%A4%96%E8%AF%AF%E7%94%A8%22%5D%20-.-%3E%20SIL%5B%22%E8%AF%81%E6%98%8E%E6%B2%89%E9%BB%98%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全进阶的密码学单元到此有语言：完善 vs 计算、游戏、归约、ROM。下一课把常见「证明外失败」列成清单，作为协议单元的入口。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 GCM 的论文全文。误用清单下一课：从 nonce 到 JWT，全部是合同外。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同态等到现在，都该能问：游戏是什么。</li><li>归约连到假设；假设外证明不说话。</li><li>ROM、具体安全、敌手能力都要写进合同。</li><li>下一课：密码学误用清单，然后进入信道。</li><li>出处：Goldwasser and Micali, 1984；Bellare and Rogaway；Katz and Lindell。</li></ul>',8))])}const D=i(h,[["render",E]]);export{B as __pageData,D as default};
